[CmdletBinding()]
param(
  [Parameter(Mandatory=$true)][ValidateSet('GenerateAuthenticationToken','GenerateJournalAuthenticationKey','GenerateDispatchLeaseAuthenticationKey','SealCredential','Remove','Restore','Validate')][string]$Action,
  [Parameter(Mandatory=$true)][string]$ProtectedStateRoot,
  [Parameter(Mandatory=$true)][string]$EnvelopePath,
  [switch]$Replace,
  [switch]$ConfirmCurrentUser
)
$ErrorActionPreference='Stop'
$utf8NoBom=New-Object Text.UTF8Encoding($false)
function Absolute([string]$Value,[string]$Label){if($Value -notmatch '^(?:[A-Za-z]:[\\/]|\\\\[^\\/]+[\\/][^\\/]+[\\/])' -or $Value -match '[\0\r\n]'){throw "$Label must be absolute."};return [IO.Path]::GetFullPath($Value)}
function Inside([string]$Root,[string]$Candidate){$prefix=$Root.TrimEnd('\')+'\';return $Candidate.Equals($Root,[StringComparison]::OrdinalIgnoreCase)-or $Candidate.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)}
function Local-AppData(){
  if($env:SXSY_TEST_MODE-ceq'1'){$test=Absolute ([string]$env:SXSY_TEST_ROOT) 'SXSY_TEST_ROOT';$candidate=Absolute ([string]$env:LOCALAPPDATA) 'LOCALAPPDATA';if($candidate.Equals($test,[StringComparison]::OrdinalIgnoreCase)-or-not(Inside $test $candidate)){throw 'Test LocalAppData must be a strict child of SXSY_TEST_ROOT.'};return $candidate}
  $value=[Environment]::GetFolderPath('LocalApplicationData');if([string]::IsNullOrWhiteSpace($value)-or-not[IO.Path]::IsPathRooted($value)){throw 'Current-user LocalApplicationData is unavailable.'};return [IO.Path]::GetFullPath($value)
}
function Assert-NoReparseSegments([string]$Candidate){
  $cursor=[IO.Path]::GetFullPath($Candidate);$segments=New-Object Collections.Generic.List[string]
  while(-not[string]::IsNullOrWhiteSpace($cursor)){$segments.Add($cursor);$parent=Split-Path -Parent $cursor;if([string]::IsNullOrWhiteSpace($parent)-or$parent-ceq$cursor){break};$cursor=$parent}
  foreach($segment in @($segments|Sort-Object{$_.Length})){if(Test-Path -LiteralPath $segment){$item=Get-Item -LiteralPath $segment -Force;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne 0){throw 'Provider-host protected storage cannot traverse a reparse point.'}}}
}
function Sha([string]$Path){$stream=[IO.File]::OpenRead($Path);$hasher=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($hasher.ComputeHash($stream))).Replace('-','').ToLowerInvariant()}finally{$hasher.Dispose();$stream.Dispose()}}
function Invoke-ProtectedAcl([string]$Path,[switch]$Directory,[switch]$InitializeOwner){$current=[Security.Principal.WindowsIdentity]::GetCurrent().User;$system=New-Object Security.Principal.SecurityIdentifier([Security.Principal.WellKnownSidType]::LocalSystemSid,$null);$security=Get-Acl -LiteralPath $Path;$owner=([Security.Principal.NTAccount]$security.Owner).Translate([Security.Principal.SecurityIdentifier]);if($owner.Value-cne$current.Value){throw 'Provider-host protected storage must already be owned by the current Windows user.'};if($Directory){$inherit=[Security.AccessControl.InheritanceFlags]::ContainerInherit-bor[Security.AccessControl.InheritanceFlags]::ObjectInherit;$info=New-Object IO.DirectoryInfo($Path)}else{$inherit=[Security.AccessControl.InheritanceFlags]::None;$info=New-Object IO.FileInfo($Path)};$security.SetAccessRuleProtection($true,$false);foreach($rule in @($security.Access)){[void]$security.RemoveAccessRuleAll($rule)};foreach($sid in @($current,$system)){$rule=New-Object Security.AccessControl.FileSystemAccessRule($sid,[Security.AccessControl.FileSystemRights]::FullControl,$inherit,[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow);[void]$security.AddAccessRule($rule)};if('System.IO.FileSystemAclExtensions'-as[type]){[IO.FileSystemAclExtensions]::SetAccessControl($info,$security)}else{$info.SetAccessControl($security)};$verified=Get-Acl -LiteralPath $Path;$verifiedOwner=([Security.Principal.NTAccount]$verified.Owner).Translate([Security.Principal.SecurityIdentifier]);if($verifiedOwner.Value-cne$current.Value-or-not$verified.AreAccessRulesProtected){throw 'Provider-host protected storage ACL provisioning failed.'}}
function New-ProtectedDirectory([string]$Path){$created=$false;if(-not(Test-Path -LiteralPath $Path -PathType Container)){New-Item -ItemType Directory -Force -Path $Path|Out-Null;$created=$true};Invoke-ProtectedAcl $Path -Directory -InitializeOwner:$created}
function Protect-File([string]$Path){Invoke-ProtectedAcl $Path}
function Validate-Envelope([string]$Path){if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){throw 'The provider-host secret envelope is missing.'};$item=Get-Item -LiteralPath $Path -Force;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne 0){throw 'The provider-host secret envelope cannot be a reparse point.'};$value=Get-Content -LiteralPath $Path -Raw|ConvertFrom-Json;$names=@($value.PSObject.Properties.Name);$missing=@(@('schema','version','protector','sealed')|Where-Object{$_ -notin $names});if($names.Count-ne 4-or $missing.Count-ne 0-or $value.schema-cne'sxsy-b122.provider-host-secret-envelope'-or $value.version-ne 1-or $value.protector-cne'windows-dpapi-current-user'-or [string]$value.sealed-cnotmatch'^[A-Za-z0-9+/]+={0,2}$'-or ([string]$value.sealed).Length-gt 32768){throw 'The provider-host DPAPI secret envelope is malformed.'};return $value}

$root=Absolute $ProtectedStateRoot 'ProtectedStateRoot';$path=Absolute $EnvelopePath 'EnvelopePath';$local=Local-AppData;$base=[IO.Path]::GetFullPath((Join-Path $local 'STRATHEX\switchyard\provider-host'))
if(-not(Inside $base $root)-or-not(Inside $root $path)){throw 'Provider-host secrets must remain beneath the dedicated current-user LocalAppData root.'}
if(-not $ConfirmCurrentUser){throw 'Secret provisioning requires explicit -ConfirmCurrentUser authorization.'}
Assert-NoReparseSegments $base;Assert-NoReparseSegments $root;Assert-NoReparseSegments (Split-Path -Parent $path);if(Test-Path -LiteralPath $path){Assert-NoReparseSegments $path}
New-ProtectedDirectory $base;New-ProtectedDirectory $root
$backup=$path+'.previous';$removed=$path+'.removed'
if($Action -ceq 'Validate'){$value=Validate-Envelope $path;Protect-File $path;[ordered]@{schema='sxsy-b122.provider-host-secret-operation';version=1;action='validate';status='passed';envelopePath=$path;envelopeSha256=(Sha $path);protector=[string]$value.protector;cleartextRead=$false}|ConvertTo-Json -Compress;return}
if($Action -ceq 'Remove'){if(-not(Test-Path -LiteralPath $path -PathType Leaf)){throw 'The provider-host secret envelope is already absent.'};Validate-Envelope $path|Out-Null;if(Test-Path -LiteralPath $removed){Remove-Item -LiteralPath $removed -Force};Move-Item -LiteralPath $path -Destination $removed;Protect-File $removed;[ordered]@{schema='sxsy-b122.provider-host-secret-operation';version=1;action='remove';status='removed';envelopePath=$path;recoverablePath=$removed;cleartextRead=$false}|ConvertTo-Json -Compress;return}
if($Action -ceq 'Restore'){if(-not(Test-Path -LiteralPath $backup -PathType Leaf) -and -not(Test-Path -LiteralPath $removed -PathType Leaf)){throw 'No recoverable provider-host secret envelope exists.'};$source=if(Test-Path -LiteralPath $backup -PathType Leaf){$backup}else{$removed};Validate-Envelope $source|Out-Null;if(Test-Path -LiteralPath $path){Move-Item -LiteralPath $path -Destination $removed -Force};Move-Item -LiteralPath $source -Destination $path -Force;Protect-File $path;[ordered]@{schema='sxsy-b122.provider-host-secret-operation';version=1;action='restore';status='restored';envelopePath=$path;envelopeSha256=(Sha $path);cleartextRead=$false}|ConvertTo-Json -Compress;return}
if((Test-Path -LiteralPath $path)-and-not $Replace){throw 'The provider-host secret envelope already exists; rotation requires -Replace.'}
$clear=$null;$random=$null;$tokenText=$null;$secureInput=$null;$bstr=[IntPtr]::Zero
try{
  if($Action -ceq 'GenerateAuthenticationToken'-or$Action-ceq'GenerateJournalAuthenticationKey'-or$Action-ceq'GenerateDispatchLeaseAuthenticationKey'){$random=New-Object byte[] 32;$rng=[Security.Cryptography.RandomNumberGenerator]::Create();try{$rng.GetBytes($random)}finally{$rng.Dispose()};$tokenText=([BitConverter]::ToString($random)).Replace('-','').ToLowerInvariant();$clear=[Text.Encoding]::ASCII.GetBytes($tokenText)}
  else{
    if([Console]::IsInputRedirected){$inputText=[Console]::In.ReadToEnd();$inputText=$inputText.TrimEnd("`r","`n")}
    else{$secureInput=Read-Host 'Provider credential (input is hidden)' -AsSecureString;$bstr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secureInput);$inputText=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr)}
    if([string]::IsNullOrEmpty($inputText)-or $inputText.Length-gt 8192-or $inputText-match '[\0\r\n]'){throw 'The hidden provider credential is empty, oversized, or malformed.'};$clear=[Text.Encoding]::UTF8.GetBytes($inputText);$inputText=$null
  }
  Add-Type -AssemblyName System.Security;$sealedBytes=[Security.Cryptography.ProtectedData]::Protect($clear,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser);try{$sealed=[Convert]::ToBase64String($sealedBytes)}finally{[Array]::Clear($sealedBytes,0,$sealedBytes.Length)}
  $document=[ordered]@{schema='sxsy-b122.provider-host-secret-envelope';version=1;protector='windows-dpapi-current-user';sealed=$sealed};$parent=Split-Path -Parent $path;New-ProtectedDirectory $parent;$temporary=Join-Path $parent ('.provider-secret-'+[guid]::NewGuid().ToString('N')+'.tmp')
  try{[IO.File]::WriteAllText($temporary,($document|ConvertTo-Json -Compress),$utf8NoBom);Protect-File $temporary;if(Test-Path -LiteralPath $path){Copy-Item -LiteralPath $path -Destination $backup -Force;Protect-File $backup};Move-Item -LiteralPath $temporary -Destination $path -Force;Protect-File $path}finally{if(Test-Path -LiteralPath $temporary){Remove-Item -LiteralPath $temporary -Force}}
  Assert-NoReparseSegments $path
  $receiptAction=if($Action-ceq'GenerateAuthenticationToken'){'generate-authentication-token'}elseif($Action-ceq'GenerateJournalAuthenticationKey'){'generate-journal-authentication-key'}elseif($Action-ceq'GenerateDispatchLeaseAuthenticationKey'){'generate-dispatch-lease-authentication-key'}else{'seal-credential'}
  [ordered]@{schema='sxsy-b122.provider-host-secret-operation';version=1;action=$receiptAction;status='sealed';envelopePath=$path;envelopeSha256=(Sha $path);protector='windows-dpapi-current-user';rotated=(Test-Path -LiteralPath $backup -PathType Leaf);cleartextOutput=$false}|ConvertTo-Json -Compress
}finally{if($bstr-ne[IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)};if($null-ne$clear){[Array]::Clear($clear,0,$clear.Length)};if($null-ne$random){[Array]::Clear($random,0,$random.Length)};$tokenText=$null;$secureInput=$null}
